  "sql": "WITH units_sold AS ( SELECT product_id, SUM(quantity) AS total_units_sold, EXTRACT(YEAR FROM order_ts) AS order_year FROM orders JOIN order_items ON orders.order_id = order_items.order_id WHERE status = 'completed' GROUP BY product_id, order_year ), ranked_units_sold AS ( SELECT product_id, order_year, total_units_sold, RANK() OVER (PARTITION BY order_year ORDER BY total_units_sold DESC) AS rank FROM units_sold ) SELECT r2024.product_id, r2024.rank AS rank_2024, r2025.rank AS rank_2025 FROM ranked_units_sold r2024 JOIN ranked_units_sold r2025 ON r2024.product_id = r2025.product_id AND r2024.order_year = 2024 AND r2025.order_year = 2025 WHERE r2025.rank <= r2024.rank + 9"
